from pathlib import Path
p=Path('/workspace/results/grpo_gsm8k')
for kind,steps in [('val_generations',(0,25,50)),('rollouts',(1,25,50))]:
 for s in steps:
  a=[json.loads(x) for x in (p/kind/f'{s}.jsonl').read_text().splitlines()]
  suspicious=[]
  for i,x in enumerate(a):
   if x['score']!=1: continue
   # Explicitly contradicted arithmetic or answer narrative containing != ground truth, while reward succeeds.
   out=x['output']; gt=x['gts'].replace(',','')
   nums=re.findall(r'-?\d[\d,]*(?:\.\d+)?',out)
   tail=out[-300:]
   suspicious.append((i,gt,len(out),tail))
  print(kind,s,'rewarded',len(suspicious),'rewarded but final != ####',sum('####' not in x[3] for x in suspicious))
  if kind=='rollouts':
   for i,x in enumerate(a):
    if x['score'] and re.search(r'(?i)(answer|therefore|thus|final|total|result)[^\n]{0,100}',x['output']):
     pass
# Examples where the frozen metric awards a response despite a visibly different stated answer.
for s in (1,25,50):
 a=[json.loads(x) for x in (p/'rollouts'/f'{s}.jsonl').read_text().splitlines()]
 for i,x in enumerate(a):
  if x['score'] and re.search(r'(?i)(answer is|final answer|therefore|thus)[^\n]*',x['output']):
   m=list(re.finditer(r'(?i)(answer is|final answer|therefore|thus)[^\n]*',x['output']))[-1]
   if str(x['gts']) not in m.group():
    print('potential contradiction',s,i,'gt',x['gts'],'match',m.group(),'tail',repr(x['output'][-200:]))
