import json,re
from pathlib import Path
p=Path('/workspace/results/grpo_gsm8k')
pat=re.compile(r'(\-?[0-9\.\,]+)')
def extract(s):
 a=pat.findall(s[-300:])
 return next((x for x in reversed(a) if x not in ('','.')),None)
for kind,steps in [('val_generations',(0,25,50)),('rollouts',(1,25,50))]:
 for s in steps:
  a=[json.loads(x) for x in (p/kind/f'{s}.jsonl').read_text().splitlines()]
  hits=[]
  for i,x in enumerate(a):
   pred=extract(x['output'])
   if pred and pred.replace(',','').replace('$','')==str(x['gts']).replace(',','') and pred!=str(x['gts']):
    hits.append((i,x,pred))
  print('\n',kind,s,'comma-equivalent wrong rewards',len(hits),'of',len(a))
  for i,x,pred in hits[:8]: print('row',i,'gt',x['gts'],'pred',repr(pred),'score',x['score'],'tail',repr(x['output'][-200:]))
  fixed=sum(float(extract(x['output']) is not None and extract(x['output']).replace(',','')==str(x['gts'])) for x in a)
  print('raw score',sum(x['score'] for x in a)/len(a),'comma normalized score',fixed/len(a))
